import React from 'react';

export default function BlocoEtapaVisual({ etapaId = 1, etapas = [], onChange, caminho = '' }) {
  const atualizarEtapa = (index, campo, valor) => {
    const novas = [...etapas];
    novas[index][campo] = valor;
    onChange(novas);
  };

  const adicionarOpcao = (index) => {
    const novas = [...etapas];
    novas[index].opcoes = [...(novas[index].opcoes || []), {
      texto: '',
      acao: 'mensagem',
      mensagem: ''
    }];
    onChange(novas);
  };

  const excluirOpcao = (etapaIndex, opcaoIndex) => {
    const novas = [...etapas];
    novas[etapaIndex].opcoes.splice(opcaoIndex, 1);
    onChange(novas);
  };

  const adicionarEtapa = () => {
    onChange([
      ...etapas,
      {
        mensagem: '',
        opcoes: []
      }
    ]);
  };

  const atualizarOpcao = (etapaIndex, opcaoIndex, campo, valor) => {
    const novas = [...etapas];
    novas[etapaIndex].opcoes[opcaoIndex][campo] = valor;
    onChange(novas);
  };

  return (
    <div className="space-y-6">
      {etapas.map((etapa, etapaIndex) => {
        const tituloEtapa = caminho
          ? `Submenu: ${caminho}`
          : `Etapa ${etapaIndex + 1}`;

        return (
          <div key={etapaIndex} className="border border-gray-300 p-4 rounded bg-white shadow">
            <h2 className="font-semibold text-lg mb-2">{tituloEtapa}</h2>

            <textarea
              value={etapa.mensagem || ''}
              onChange={(e) => atualizarEtapa(etapaIndex, 'mensagem', e.target.value)}
              placeholder="Mensagem da etapa..."
              className="w-full p-2 border rounded text-sm mb-4 h-24"
            />

            <div className="space-y-3">
              {(etapa.opcoes || []).map((opcao, opcaoIndex) => (
                <div
                  key={opcaoIndex}
                  className="bg-gray-50 p-3 rounded border border-gray-300 relative"
                >
                  <button
                    onClick={() => excluirOpcao(etapaIndex, opcaoIndex)}
                    className="absolute top-2 right-2 text-red-500 text-sm"
                    title="Excluir opção"
                  >
                    🗑️
                  </button>

                  <input
                    value={opcao.texto || ''}
                    onChange={(e) => atualizarOpcao(etapaIndex, opcaoIndex, 'texto', e.target.value)}
                    placeholder={`Texto da opção ${opcaoIndex + 1}`}
                    className="border p-1 rounded w-full mb-2 text-sm"
                  />

                  <select
                    value={opcao.acao || 'mensagem'}
                    onChange={(e) => atualizarOpcao(etapaIndex, opcaoIndex, 'acao', e.target.value)}
                    className="border p-2 rounded w-full text-sm mb-2"
                  >
                    <option value="mensagem">💬 Mensagem</option>
                    <option value="subetapa">🔁 Ir para novo menu</option>
                    <option value="redirecionar">📞 Redirecionar</option>
                    <option value="arquivo">📎 Enviar arquivo</option>
                  </select>

                  {/* Mensagem associada à ação */}
                  {['mensagem', 'subetapa', 'redirecionar', 'arquivo'].includes(opcao.acao) && (
                    <textarea
                      placeholder="Mensagem que será enviada com a ação..."
                      value={opcao.mensagem || ''}
                      onChange={(e) => atualizarOpcao(etapaIndex, opcaoIndex, 'mensagem', e.target.value)}
                      className="w-full border rounded p-2 text-sm mb-2 h-20"
                    />
                  )}

                  {opcao.acao === 'redirecionar' && (
                    <input
                      type="text"
                      placeholder="Número de WhatsApp"
                      value={opcao.destino || ''}
                      onChange={(e) => atualizarOpcao(etapaIndex, opcaoIndex, 'destino', e.target.value)}
                      className="mt-1 border p-2 rounded w-full text-sm"
                    />
                  )}

                  {opcao.acao === 'arquivo' && (
                    <input
                      type="file"
                      className="mt-1 text-sm"
                      onChange={(e) =>
                        atualizarOpcao(etapaIndex, opcaoIndex, 'arquivo', e.target.files[0])
                      }
                    />
                  )}

                  {opcao.acao === 'subetapa' && (
                    <div className="ml-4 mt-4 border-l-4 border-blue-300 pl-4">
                      <BlocoEtapaVisual
                        etapaId={`${etapaId}.${etapaIndex + 1}.${opcaoIndex + 1}`}
                        etapas={opcao.subetapas || []}
                        onChange={(novas) =>
                          atualizarOpcao(etapaIndex, opcaoIndex, 'subetapas', novas)
                        }
                        caminho={caminho ? `${caminho} > ${opcao.texto}` : opcao.texto}
                      />
                    </div>
                  )}
                </div>
              ))}
            </div>

            <button
              onClick={() => adicionarOpcao(etapaIndex)}
              className="mt-3 bg-blue-600 text-white px-4 py-1 rounded text-sm hover:bg-blue-700"
            >
              ➕ Adicionar Opção
            </button>
          </div>
        );
      })}

      <button
        onClick={adicionarEtapa}
        className="bg-green-600 text-white px-4 py-2 rounded text-sm hover:bg-green-700"
      >
        ➕ Adicionar Nova Etapa
      </button>
    </div>
  );
}
